package com.vandorlabs.neoforge.door;

import com.vandorlabs.neoforge.fluid.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.material.Fluids;
import net.neoforged.neoforge.fluids.FluidStack;

/** Actual registered linked hosts; geometry itself has a separate frozen Forge replay. */
final class DoorFluidHostChecks {
    private static int checks;
    private static void need(boolean value,String message){checks++;if(!value)throw new AssertionError("Door fluid host: "+message);}
    static void run(ServerLevel level,NativeProgrammableDoorEntity lower){
        var upper=(NativeProgrammableDoorEntity)level.getBlockEntity(lower.getBlockPos().above());
        lower.refreshFluidGeometry();upper.refreshFluidGeometry();
        need(lower.openingFluidVolume()&&upper.openingFluidVolume(),"both installed parts publish opening volumes");
        need(lower.containedFluids()!=upper.containedFluids(),"parts retain independent slot owners");
        var volume=lower.fluidVolumeSnapshot();long revision=lower.fluidGeometryRevision();lower.refreshFluidGeometry();
        need(lower.fluidVolumeSnapshot()==volume&&lower.fluidGeometryRevision()==revision,"unchanged geometry retains identity and revision");
        var facing=lower.fluidPlacementFaces();need(facing.length==2&&facing[0].getOpposite()==facing[1],"opening placement samples both normal faces");
        var tag=upper.saveWithoutMetadata(level.registryAccess());var raw=new CompoundTag();raw.putString("id","fixture:missing_fluid");raw.putInt("amount",1000);raw.putString("Unknown","retain");var slots=new CompoundTag();slots.put("Side1",raw);tag.put(NativeFluidSlots.KEY,slots);upper.loadWithComponents(tag,level.registryAccess());upper.refreshFluidGeometry();
        need(upper.containedFluids().occupied(1)&&upper.containedFluids().get(1).isEmpty(),"unknown occupied slot stays inert");
        need(upper.saveWithoutMetadata(level.registryAccess()).getCompound(NativeFluidSlots.KEY).getCompound("Side1").equals(raw),"unknown upper slot saves losslessly");
        need(!NativeFluidWorld.canFill(upper,1,new FluidStack(Fluids.WATER,1000)),"bucket availability rejects opaque occupancy");
        need(NativeFluidWorld.set(lower,0,new FluidStack(Fluids.WATER,1000)),"installed lower water mutation");
        need(lower.containedFluids().get(0).getFluid()==Fluids.WATER&&!upper.containedFluids().occupied(0),"lower mutation cannot change upper slots");
        lower.refreshFluidGeometry();var exposed=lower.fluidSurfaceRegions();need(exposed.regions().get(0).planes().get(3).distance()==.999,"exposed Door water retains source frame clearance");need(!NativeFluidSurface.surfaces(volume,exposed,0,null,null).isEmpty()&&!volume.facesMaterialized(),"Door render preparation avoids physical face graph");upper.containedFluids().set(0,new FluidStack(Fluids.WATER,333),level.registryAccess());upper.refreshFluidGeometry();lower.refreshFluidGeometry();need(lower.fluidSurfaceRegions().regions().get(0).planes().get(3).distance()==1,"same components above retain full internal height irrespective amount");upper.containedFluids().set(0,FluidStack.EMPTY,level.registryAccess());upper.refreshFluidGeometry();lower.refreshFluidGeometry();need(lower.fluidSurfaceRegions().regions().get(0).planes().get(3).distance()==.999,"removing above fluid restores exposed height");var cachedRegions=lower.fluidSurfaceRegions();lower.refreshFluidGeometry();need(lower.fluidSurfaceRegions()==cachedRegions,"unchanged Door regions retain identity");
        var publicTag=lower.getUpdateTag(level.registryAccess());need(publicTag.contains(NativeFluidSlots.KEY,10),"explicit fluid render projection synchronized");
        need(!lower.itemSettings().contains(NativeFluidSlots.KEY),"configured item excludes runtime fluid ownership");
        int luminous=-1,emission=0;for(var choice:com.vandorlabs.neoforge.ModernFinishCatalog.allChoices())if(choice.entry().frame()!=null&&choice.entry().frame().light()>0){luminous=choice.choice();emission=Math.max(0,Math.min(5,choice.entry().frame().light()));break;}
        need(luminous>=0,"canonical luminous frame exists");var originalFrames=lower.settings().frames();lower.stageFrames(new com.vandorlabs.persistence.FrameSettings(luminous,-1,-1,0,-1,-1,false,false,false,false));need(lower.intrinsicContainedLight()==emission,"framed door emits current frame metadata light");
        lower.stageFrames(new com.vandorlabs.persistence.FrameSettings(luminous,-1,-1,0,-1,-1,false,false,false,true));need(lower.intrinsicContainedLight()==0,"bare frame suppresses front emission");lower.stageFrames(originalFrames);
        var aux=level.getAuxLightManager(lower.getBlockPos());aux.setLightAt(lower.getBlockPos(),7);int workerLight=java.util.concurrent.CompletableFuture.supplyAsync(()->lower.getBlockState().getLightEmission(level,lower.getBlockPos())).join();need(workerLight==7,"actual light-emission worker reads only auxiliary manager");aux.setLightAt(lower.getBlockPos(),0);
        var snapshot=lower.containedFluids().snapshot();var copy=snapshot.side(0).fluid();copy.setAmount(1);need(snapshot.side(0).fluid().getAmount()==1000,"published slot snapshot cannot leak mutable stacks");
        need(lower.getModelData().get(NativeFluidRenderSnapshot.DATA)==lower.fluidRenderSnapshot(),"worker model snapshot includes published fluid data only");
        var taggedWater=new FluidStack(Fluids.WATER,777);var marker=new CompoundTag();marker.putString("Owner","fixture:water");taggedWater.set(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.of(marker));upper.containedFluids().set(0,taggedWater,level.registryAccess());
        var rootState=lower.getBlockState();level.setBlock(lower.getBlockPos(),rootState.setValue(NativeProgrammableDoorBlock.OPEN,true),net.minecraft.world.level.block.Block.UPDATE_CLIENTS);upper.refreshFluidGeometry();var borrowed=upper.effectiveFluidSnapshot().side(1).fluid();need(FluidStack.isSameFluidSameComponents(taggedWater,borrowed)&&borrowed.getAmount()==777,"upper effective fill uses root OPEN and retains opposite amount/components despite opaque slot");
        need(upper.fluidSurfaceRegions().regions().size()==1,"root OPEN joins equal effective fluids despite per-half metadata disagreement");need(upper.containedFluids().raw(1).equals(raw),"derived water never changes opaque saved ownership");var effective=upper.effectiveFluidSnapshot();upper.refreshFluidGeometry();need(upper.effectiveFluidSnapshot()==effective,"unchanged opening publication retains snapshot identity");var repeated=upper.saveWithoutMetadata(level.registryAccess());upper.loadWithComponents(repeated,level.registryAccess());upper.refreshFluidGeometry();need(upper.effectiveFluidSnapshot()==effective,"repeated identical packet/save does not advance effective fluid revision");
        NativeFluidWorld.changed(upper);var cell=upper.fluidVolumeSnapshot().cells().stream().filter(c->c.side()==1).findFirst().orElseThrow();var box=cell.box();var point=new net.minecraft.world.phys.Vec3(upper.getBlockPos().getX()+(box.minX+box.maxX)/2,upper.getBlockPos().getY()+(box.minY+box.maxY)/2,upper.getBlockPos().getZ()+(box.minZ+box.maxZ)/2);need(FluidStack.isSameFluidSameComponents(taggedWater,NativeFluidWorld.atPoint(level,point)),"actual contact query consumes effective tagged water");
        level.setBlock(lower.getBlockPos(),rootState,net.minecraft.world.level.block.Block.UPDATE_CLIENTS);upper.containedFluids().set(0,FluidStack.EMPTY,level.registryAccess());var normal=lower.fluidPlacementFaces()[0];var neighbor=upper.getBlockPos().relative(normal);var previous=level.getBlockState(neighbor);level.setBlock(neighbor,net.minecraft.world.level.block.Blocks.WATER.defaultBlockState(),net.minecraft.world.level.block.Block.UPDATE_CLIENTS);upper.refreshFluidGeometry();need(upper.effectiveFluidSnapshot().side(1).fluid().is(Fluids.WATER)&&upper.effectiveFluidSnapshot().side(1).fluid().getAmount()==1000,"closed opening takes directly adjacent normal-side ambient water only");need(!NativeFluidWorld.canFill(upper,1,new FluidStack(Fluids.LAVA,1000)),"ambient fill cannot authorize overwriting opaque ownership");level.setBlock(neighbor,previous,net.minecraft.world.level.block.Block.UPDATE_CLIENTS);upper.refreshFluidGeometry();need(upper.effectiveFluidSnapshot().side(1).fluid().isEmpty()&&upper.containedFluids().occupied(1),"ambient removal reverses derived fill without clearing unknown data");
        lower.containedFluids().set(0,FluidStack.EMPTY,level.registryAccess());upper.containedFluids().set(1,FluidStack.EMPTY,level.registryAccess());lower.containedFluidsChanged();upper.containedFluidsChanged();
        System.out.println("[vandorlabs][door-fluid-host] PASS checks="+checks+" per-half storage/opaque ownership/published geometry/effective ambient contact; gush separate");
    }
}
